The following program demonstrates how to count the number of occurrences of a word in a text file using C++. The program uses an input file, which contains some sample text, and reads it line by line. For each line, it checks if the given word is present in the line and increments a counter if it is found. Finally, the total number of occurrences is printed to the console. 
```c++
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    string word; // Word to search for
    int count = 0; // Counter variable

    ifstream file("input.txt"); // Input file name
    if (file.is_open()) {
        while (file) {
            getline(file, word); // Read a line from the file
            if (word == "the") // Check if the word is present in the line
                count++; // Increment the counter if found
        }
        file.close(); // Close the file
    } else {
        cout << "Error: File not found." << endl;
    }

    cout << "Word 'the' occurred " << count << " times in the input file." << endl;
    return 0;
}
